import Ajv from 'ajv';
const ajv = new Ajv({allErrors: true, strict: false, validateFormats: false, coerceTypes: false, useDefaults: false});
const schema = {
  type: 'object',
  properties: {
    location: { type: 'string' },
    ssn: { type: 'string' }
  },
  required: ['location']
};
const validate = ajv.compile(schema);
validate({ ssn: 12345 });

function formatValidationError(err) {
  const dataPath = ((err.instancePath ?? err.dataPath ?? ''))
    .replace(/^[\./]/, '')
    .replace(/\//g, '.');
  if (err.keyword === 'required' && typeof err.params?.missingProperty === 'string') {
    const field = dataPath ? \`\${dataPath}.\${err.params.missingProperty}\` : err.params.missingProperty;
    return \`missing required property '\${field}'\`;
  }
  if (dataPath) {
    return \`property '\${dataPath}' \${err.message ?? 'is invalid'}\`;
  }
  return err.message ?? 'validation failed';
}

const errors = validate.errors.map(formatValidationError);
console.log('Formatted:', errors);
console.log('Result string:', \`Invalid input: \${errors.join('; ')}\`);
"

